def forbid_multi_line_headers(name, val):
    """Forbid multi-line headers, to prevent header injection."""
    val = smart_text(val)
    if "\n" in val or "\r" in val:
        raise BadHeaderError(
            "Header values can't contain newlines "
            "(got %r for header %r)" % (val, name)
        )
    try:
        val = val.encode("ascii")
    except UnicodeEncodeError:
        if name.lower() in ("to", "from", "cc"):
            result = []
            for item in val.split(", "):
                nm, addr = parseaddr(item)
                nm = str(Header(nm, DEFAULT_CHARSET))
                result.append(formataddr((nm, str(addr))))
            val = ", ".join(result)
        else:
            val = Header(val, DEFAULT_CHARSET)
    else:
        if name.lower() == "subject":
            val = Header(val)
    return name, val

def process(self):
        """ Receive data from socket and process request """

        response = None

        try:
            payload = self.receive()
            method, args, ref = self.parse(payload)
            response = self.execute(method, args, ref)

        except AuthenticateError as exception:
            logging.error(
                'Service error while authenticating request: {}'
                .format(exception), exc_info=1)

        except AuthenticatorInvalidSignature as exception:
            logging.error(
                'Service error while authenticating request: {}'
                .format(exception), exc_info=1)

        except DecodeError as exception:
            logging.error(
                'Service error while decoding request: {}'
                .format(exception), exc_info=1)

        except RequestParseError as exception:
            logging.error(
                'Service error while parsing request: {}'
                .format(exception), exc_info=1)

        else:
            logging.debug('Service received payload: {}'.format(payload))

        if response:
            self.send(response)
        else:
            self.send('')

def watson_request(text, synth_args):
    """
    Makes a single request to the IBM Watson text-to-speech API.

    :param text:
        The text that will be synthesized to audio.
    :param synth_args:
        A dictionary of arguments to add to the request. These should include
        username and password for authentication.
    """
    params = {
        'text': text,
        'accept': 'audio/wav'
    }
    if synth_args is not None:
        params.update(synth_args)

    if 'username' in params:
        username = params.pop('username')
    else:
        raise Warning('The IBM Watson API requires credentials that should be passed as "username" and "password" in "synth_args"')
    if 'password' in params:
        password = params.pop('password')
    else:
        raise Warning('The IBM Watson API requires credentials that should be passed as "username" and "password" in "synth_args"')

    return requests.get(watson_url, auth=(username, password), params=params)

def remove_exponent(d):
    """Remove exponent."""
    return d.quantize(Decimal(1)) if d == d.to_integral() else d.normalize()

def apply(self, callback, context):  # pragma: no cover
        """Apply the HTTPError wrapper to the callback.
        """

        def wrapper(*args, **kwargs):
            try:
                return callback(*args, **kwargs)
            except bottle.HTTPError as error:
                return self.error_wrapper.from_status(
                    status_line=error.status_line,
                    msg=error.body
                )

        return wrapper

def get_py_files(dir_name: str) -> list:
    """Get all .py files."""
    return flatten([
        x for x in
        [["{0}/{1}".format(path, f) for f in files if f.endswith(".py")]
         for path, _, files in os.walk(dir_name)
         if not path.startswith("./build")] if x
    ])

def raw(self):
        """Return raw key.

        returns:
            str: raw key
        """
        if self._raw:
            return text_type(self._raw).strip("\r\n")
        else:
            return text_type(base64decode(self._b64encoded)).strip("\r\n")

def _assert_precondition(contract: Contract, resolved_kwargs: Mapping[str, Any]) -> None:
    """
    Assert that the contract holds as a precondition.

    :param contract: contract to be verified
    :param resolved_kwargs: resolved keyword arguments (including the default values)
    :return:
    """
    # Check that all arguments to the condition function have been set.
    missing_args = [arg_name for arg_name in contract.condition_args if arg_name not in resolved_kwargs]
    if missing_args:
        raise TypeError(
            ("The argument(s) of the precondition have not been set: {}. "
             "Does the original function define them? Did you supply them in the call?").format(missing_args))

    condition_kwargs = {
        arg_name: value
        for arg_name, value in resolved_kwargs.items() if arg_name in contract.condition_arg_set
    }

    check = contract.condition(**condition_kwargs)

    if not check:
        if contract.error is not None and (inspect.ismethod(contract.error) or inspect.isfunction(contract.error)):
            assert contract.error_arg_set is not None, "Expected error_arg_set non-None if contract.error a function."
            assert contract.error_args is not None, "Expected error_args non-None if contract.error a function."

            error_kwargs = {
                arg_name: value
                for arg_name, value in resolved_kwargs.items() if arg_name in contract.error_arg_set
            }

            missing_args = [arg_name for arg_name in contract.error_args if arg_name not in resolved_kwargs]
            if missing_args:
                msg_parts = []  # type: List[str]
                if contract.location is not None:
                    msg_parts.append("{}:\n".format(contract.location))

                msg_parts.append(
                    ("The argument(s) of the precondition error have not been set: {}. "
                     "Does the original function define them? Did you supply them in the call?").format(missing_args))

                raise TypeError(''.join(msg_parts))

            raise contract.error(**error_kwargs)

        else:
            msg = icontract._represent.generate_message(contract=contract, condition_kwargs=condition_kwargs)
            if contract.error is None:
                raise ViolationError(msg)
            elif isinstance(contract.error, type):
                raise contract.error(msg)

def _safe_get(mapping, key, default=None):
    """Helper for accessing style values.

    It exists to avoid checking whether `mapping` is indeed a mapping before
    trying to get a key.  In the context of style dicts, this eliminates "is
    this a mapping" checks in two common situations: 1) a style argument is
    None, and 2) a style key's value (e.g., width) can be either a mapping or a
    plain value.
    """
    try:
        return mapping.get(key, default)
    except AttributeError:
        return default

def bump(args: argparse.Namespace) -> None:
    """
    :args: An argparse.Namespace object.

    This function is bound to the 'bump' sub-command. It increments the version
    integer of the user's choice ('major', 'minor', or 'patch').
    """
    try:
        last_tag = last_git_release_tag(git_tags())
    except NoGitTagsException:
        print(SemVer(0, 1, 0))
        exit(0)

    last_ver = git_tag_to_semver(last_tag)

    if args.type == 'patch':
        print(last_ver.bump_patch())
    elif args.type == 'minor':
        print(last_ver.bump_minor())
    elif args.type == 'major':
        print(last_ver.bump_major())

def create(self, data):
        """Create a new component
        """
        response = self.http.post(str(self), json=data, auth=self.auth)
        response.raise_for_status()
        return response.json()
